/**
 * Personal API token rows. Stores only the SHA-256 digest of each secret;
 * the plaintext never reaches this layer.
 *
 * Must call (do not reimplement): orgPredicate, toApiToken
 */
import { and, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { apiTokens, getDb } from "@/server/db";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toApiToken } from "./_mappers";

export interface NewApiToken {
  readonly id: string;
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly tokenHash: string;
  readonly prefix: string;
  readonly expiresAt: IsoTimestamp;
}

/** Usable means not revoked and not yet expired at `now`. */
function usablePredicate(orgId: OrgId, userId: UserId, now: IsoTimestamp) {
  return and(
    orgPredicate(apiTokens.orgId, orgId),
    eq(apiTokens.userId, userId),
    isNull(apiTokens.revokedAt),
    gt(apiTokens.expiresAt, now),
  );
}

/**
 * Counts the user's usable tokens and inserts the new one in a single
 * synchronous transaction, so two concurrent creates cannot both pass the
 * limit check. Resolves `null` (and stores nothing) when the limit is reached.
 */
export async function insertApiTokenUnderLimit(
  input: NewApiToken,
  limit: number,
  now: IsoTimestamp,
): Promise<ApiToken | null> {
  return getDb().transaction((tx) => {
    const usable = tx
      .select({ value: count() })
      .from(apiTokens)
      .where(usablePredicate(input.orgId, input.userId, now))
      .get();

    if ((usable?.value ?? 0) >= limit) return null;

    const row = tx
      .insert(apiTokens)
      .values({
        id: input.id,
        orgId: input.orgId,
        userId: input.userId,
        name: input.name,
        scope: input.scope,
        tokenHash: input.tokenHash,
        prefix: input.prefix,
        expiresAt: input.expiresAt,
        lastUsedAt: null,
        revokedAt: null,
        createdAt: now,
        updatedAt: now,
      })
      .returning()
      .get();

    return toApiToken(row);
  });
}

/** Cross-tenant on purpose: authentication starts from the secret, not an org. */
export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

/** Newest first; `rowid` breaks ties between tokens created in the same millisecond. */
export async function listApiTokens(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
      ),
    )
    .orderBy(desc(apiTokens.createdAt), desc(sql`rowid`))
    .all();
  return rows.map(toApiToken);
}

/**
 * Sets `revoked_at` only while the token is still live. Resolves `null` when
 * the token is missing or already revoked, so the caller can tell the two apart
 * from a fresh revocation.
 */
export async function revokeApiToken(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();
  return row ? toApiToken(row) : null;
}

/** Revokes every not-yet-revoked token of one user in one org, expired ones included. */
export async function revokeActiveApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .update(apiTokens)
    .set({ revokedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .all();
  return rows.map(toApiToken);
}

export async function touchApiTokenLastUsed(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(apiTokens)
    .set({ lastUsedAt: at, updatedAt: at })
    .where(
      and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)),
    )
    .run();
}

