/**
 * Personal API tokens: minting, listing and revoking them, and resolving a
 * presented secret back to the `Actor` it acts as.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, subscribe, hashToken, randomToken, resolveActor
 */
import { emit, subscribe } from "@/lib/event-bus";
import { newId } from "@/lib/id";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, envelope, orgResource, requireFound } from "./_support";
import { resolveActor } from "./member-service";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

/** Every secret starts with this, so a leaked one is recognisable in logs. */
const TOKEN_PREFIX = "tfk_";

/** Bytes of randomness in the secret; the encoded form is URL-safe base64. */
const SECRET_BYTES = 32;

/** Leading characters of the secret kept in clear as `ApiToken.prefix`. */
const PREFIX_LENGTH = 12;

const MAX_USABLE_TOKENS_PER_USER = 5;

const DAY_MS = 24 * 60 * 60 * 1000;

/**
 * Mints a token and returns its secret exactly once. Only the SHA-256 digest is
 * stored, so the secret cannot be shown again later.
 */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);
  assertCan(actor, "api_token:create", orgResource(parsed.orgId));
  if (parsed.scope === "write") {
    assertCan(actor, "api_token:create_write", orgResource(parsed.orgId));
  }

  const createdAt = new Date();
  const expiresAt = toIsoTimestamp(
    new Date(createdAt.getTime() + parsed.expiresInDays * DAY_MS),
  );
  const token = `${TOKEN_PREFIX}${randomToken(SECRET_BYTES)}`;

  const apiToken = await apiTokenRepo.insertApiTokenUnderLimit(
    {
      id: newId(),
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      tokenHash: hashToken(token),
      prefix: token.slice(0, PREFIX_LENGTH),
      expiresAt,
    },
    MAX_USABLE_TOKENS_PER_USER,
    toIsoTimestamp(createdAt),
  );

  if (apiToken === null) {
    throw new Error(
      `You can hold at most ${MAX_USABLE_TOKENS_PER_USER} usable API tokens per organization; revoke or wait for one to expire first`,
    );
  }

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
}

/**
 * Tokens of `userId` (default: the actor) in one org, newest first, including
 * revoked and expired ones. Reading someone else's list is an admin action.
 */
export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId?: UserId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);

  const owner = userId ?? actor.userId;
  if (owner !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }

  return apiTokenRepo.listApiTokens(orgId, owner);
}

/**
 * Revokes a token. Idempotent: revoking a token that is already revoked returns
 * it unchanged, keeps its original `revokedAt`, and records nothing new.
 */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "API token",
    tokenId,
  );
  if (existing.userId !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }

  const revoked = await apiTokenRepo.revokeApiToken(
    orgId,
    tokenId,
    toIsoTimestamp(new Date()),
  );

  if (revoked === null) {
    return requireFound(
      await apiTokenRepo.findApiTokenById(orgId, tokenId),
      "API token",
      tokenId,
    );
  }

  await emit("api_token.revoked", {
    ...actorEnvelope(actor),
    tokenId: revoked.id,
    userId: revoked.userId,
  });

  return revoked;
}

/**
 * The `Actor` a presented secret acts as, or `null` when it cannot be used.
 * A `read` token acts as a viewer; a `write` token acts as its owner's current
 * role, so promotions and demotions apply to it immediately.
 */
export async function authenticateApiToken(token: string): Promise<Actor | null> {
  if (!token.startsWith(TOKEN_PREFIX)) return null;

  const row = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (row === null || row.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  if (row.expiresAt <= now) return null;

  const org = await orgRepo.findOrgById(row.orgId);
  if (org === null || org.archivedAt !== null) return null;

  const member = await resolveActor(row.userId, row.orgId);
  if (member === null) return null;

  await apiTokenRepo.touchApiTokenLastUsed(row.orgId, row.id, now);

  return {
    userId: row.userId,
    orgId: row.orgId,
    role: row.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * Removing a member revokes every live token they hold in that org, expired
 * ones included, and audits each revocation under the remover. Tokens already
 * revoked are left alone.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const revoked = await apiTokenRepo.revokeActiveApiTokensForUser(
      payload.orgId,
      payload.userId,
      toIsoTimestamp(new Date()),
    );

    for (const token of revoked) {
      await emit("api_token.revoked", {
        ...envelope(payload.orgId, payload.actorId),
        tokenId: token.id,
        userId: token.userId,
      });
    }
  });
}

export type { IsoTimestamp };

