  );

  if (revoked === null) {
    return requireFound(
      await apiTokenRepo.findApiTokenById(orgId, tokenId),
      "API token",
      tokenId,
    );
  }

  await emit("api_token.revoked", {
    ...actorEnvelope(actor),
    tokenId: revoked.id,
    userId: revoked.userId,
  });

  return revoked;
}

/**
 * The `Actor` a presented secret acts as, or `null` when it cannot be used.
 * A `read` token acts as a viewer; a `write` token acts as its owner's current
 * role, so promotions and demotions apply to it immediately.
 */
export async function authenticateApiToken(token: string): Promise<Actor | null> {
  if (!token.startsWith(TOKEN_PREFIX)) return null;

  const row = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (row === null || row.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  if (row.expiresAt <= now) return null;

  const org = await orgRepo.findOrgById(row.orgId);
  if (org === null || org.archivedAt !== null) return null;

  const member = await resolveActor(row.userId, row.orgId);
  if (member === null) return null;

  await apiTokenRepo.touchApiTokenLastUsed(row.orgId, row.id, now);

  return {
    userId: row.userId,
    orgId: row.orgId,
    role: row.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * Removing a member revokes every live token they hold in that org, expired
 * ones included, and audits each revocation under the remover. Tokens already
 * revoked are left alone.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", async (payload) => {
    const revoked = await apiTokenRepo.revokeActiveApiTokensForUser(
      payload.orgId,
      payload.userId,
      toIsoTimestamp(new Date()),
    );

    for (const token of revoked) {
      await emit("api_token.revoked", {
        ...envelope(payload.orgId, payload.actorId),
        tokenId: token.id,
        userId: token.userId,
      });
    }
  });
}

export type { IsoTimestamp };

