import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";
import { ZodError } from "zod";
import { getDb } from "@/server/db";
import { users } from "@/server/db/schema/users";
import { activityEvents } from "@/server/db/schema/activity";
import { setupTestDb, resetTestDb, seedTwoTenants } from "../helpers/db";
import { ALICE, BOB, makeActor, ORG_A } from "../helpers/factories";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import * as apiTokenService from "@/server/services/api-token-service";
import * as memberService from "@/server/services/member-service";
import * as memberRepo from "@/server/repositories/member-repository";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import type { OrgId, UserId } from "@/types/common";
import type { Actor } from "@/types/member";

let owner: Actor;
let memberActor: Actor;
let viewerActor: Actor;
let memberId: string;
let viewerMemberId: string;

async function addUser(id: UserId, email: string) {
  await getDb().insert(users).values({ id, email, name: email, passwordHash: "x", timezone: "UTC" }).onConflictDoNothing();
}

beforeAll(async () => {
  await setupTestDb();
  registerEventHandlers();
});

beforeEach(async () => {
  await resetTestDb();
  const { orgA } = await seedTwoTenants();
  await addUser(ALICE, "alice@example.com");
  await addUser(BOB, "bob@example.com");
  const viewerId = "01HZZZVVVVVVVVVVVVVVVVVVV1" as UserId;
  await addUser(viewerId, "viewer@example.com");
  await memberRepo.insertMember(ORG_A, orgA.ownerId, "owner", null);
  const m = await memberRepo.insertMember(ORG_A, ALICE, "member", null);
  const v = await memberRepo.insertMember(ORG_A, viewerId, "viewer", null);
  memberId = m.id; viewerMemberId = v.id;
  owner = { userId: orgA.ownerId, orgId: ORG_A, role: "owner" };
  memberActor = { userId: ALICE, orgId: ORG_A, role: "member" };
  viewerActor = { userId: viewerId, orgId: ORG_A, role: "viewer" };
});

afterEach(() => { vi.useRealTimers(); });

const input = (over: Record<string, unknown> = {}) => ({ orgId: ORG_A, name: "  ci  ", scope: "read" as const, expiresInDays: 30, ...over }) as any;

describe("api tokens", () => {
  it("creates, authenticates, audits", async () => {
    const { token, apiToken } = await apiTokenService.createApiToken(memberActor, input());
    expect(token.startsWith("tfk_")).toBe(true);
    expect(apiToken.prefix).toBe(token.slice(0, 12));
    expect(apiToken.name).toBe("ci");
    expect(JSON.stringify(apiToken)).not.toContain("hash");
    expect(apiToken.lastUsedAt).toBeNull();
    expect(apiToken.revokedAt).toBeNull();
    const ms = Date.parse(apiToken.expiresAt) - Date.parse(apiToken.createdAt);
    expect(ms).toBe(30 * 24 * 3600 * 1000);
    const actor = await apiTokenService.authenticateApiToken(token);
    expect(actor).toEqual({ userId: ALICE, orgId: ORG_A, role: "viewer" });
    const listed = await apiTokenService.listApiTokens(memberActor, ORG_A);
    expect(listed[0]!.lastUsedAt).not.toBeNull();
    const rows = getDb().select().from(activityEvents).all();
    const created = rows.find((r) => r.action === "api_token.created")!;
    expect(created.subjectKind).toBe("api_token");
    expect(created.subjectId).toBe(apiToken.id);
    expect(created.actorId).toBe(ALICE);
    expect(JSON.stringify(rows)).not.toContain(token);
  });

  it("validates input and enforces roles", async () => {
    await expect(apiTokenService.createApiToken(memberActor, input({ expiresInDays: 0 }))).rejects.toBeInstanceOf(ZodError);
    await expect(apiTokenService.createApiToken(memberActor, input({ orgId: "01HZZZBBBBBBBBBBBBBBBBBBBB" }))).rejects.toBeInstanceOf(TenantScopeError);
    await expect(apiTokenService.createApiToken(viewerActor, input({ scope: "write" }))).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(apiTokenService.createApiToken(viewerActor, input())).resolves.toBeTruthy();
    const w = await apiTokenService.createApiToken(memberActor, input({ scope: "write" }));
    expect(await apiTokenService.authenticateApiToken(w.token)).toEqual({ userId: ALICE, orgId: ORG_A, role: "member" });
  });

  it("caps usable tokens at 5 per user, ignoring revoked and expired", async () => {
    const made = [];
    for (let i = 0; i < 5; i++) made.push(await apiTokenService.createApiToken(memberActor, input({ name: `t${i}` })));
    await expect(apiTokenService.createApiToken(memberActor, input())).rejects.toThrow();
    expect(await apiTokenService.listApiTokens(memberActor, ORG_A)).toHaveLength(5);
    await apiTokenService.createApiToken(owner, input());
    await apiTokenService.revokeApiToken(memberActor, ORG_A, made[0]!.apiToken.id);
    await apiTokenService.createApiToken(memberActor, input());
    await expect(apiTokenService.createApiToken(memberActor, input())).rejects.toThrow();
  });

  it("lists newest first, others need admin, revoke is idempotent", async () => {
    const a = await apiTokenService.createApiToken(memberActor, input({ name: "a" }));
    const b = await apiTokenService.createApiToken(memberActor, input({ name: "b" }));
    const list = await apiTokenService.listApiTokens(memberActor, ORG_A);
    expect(list.map((t) => t.name)).toEqual(["b", "a"]);
    await expect(apiTokenService.listApiTokens(viewerActor, ORG_A, ALICE)).rejects.toBeInstanceOf(PermissionDeniedError);
    expect(await apiTokenService.listApiTokens(owner, ORG_A, ALICE)).toHaveLength(2);
    await expect(apiTokenService.revokeApiToken(viewerActor, ORG_A, a.apiToken.id)).rejects.toBeInstanceOf(PermissionDeniedError);
    const r1 = await apiTokenService.revokeApiToken(memberActor, ORG_A, a.apiToken.id);
    const r2 = await apiTokenService.revokeApiToken(memberActor, ORG_A, a.apiToken.id);
    expect(r2.revokedAt).toBe(r1.revokedAt);
    expect(await apiTokenService.authenticateApiToken(a.token)).toBeNull();
    const audits = getDb().select().from(activityEvents).all().filter((r) => r.action === "api_token.revoked");
    expect(audits).toHaveLength(1);
    await expect(apiTokenService.revokeApiToken(memberActor, ORG_A, "nope")).rejects.toMatchObject({ code: "not_found" });
    void b;
  });

  it("expires at exactly expiresAt", async () => {
    vi.useFakeTimers({ now: new Date("2026-01-01T00:00:00.000Z") });
    const { token } = await apiTokenService.createApiToken(memberActor, input({ expiresInDays: 1 }));
    vi.setSystemTime(new Date("2026-01-01T23:59:59.999Z"));
    expect(await apiTokenService.authenticateApiToken(token)).not.toBeNull();
    vi.setSystemTime(new Date("2026-01-02T00:00:00.000Z"));
    expect(await apiTokenService.authenticateApiToken(token)).toBeNull();
  });

  it("removing a member revokes their tokens, audited under the remover", async () => {
    const live = await apiTokenService.createApiToken(memberActor, input({ scope: "write" }));
    await apiTokenService.createApiToken(viewerActor, input());
    await memberService.removeMember(owner, { orgId: ORG_A, memberId } as any);
    expect(await apiTokenService.authenticateApiToken(live.token)).toBeNull();
    const audits = getDb().select().from(activityEvents).all().filter((r) => r.action === "api_token.revoked");
    expect(audits.some((r) => r.subjectId === live.apiToken.id && r.actorId === owner.userId)).toBe(true);
    expect(await apiTokenService.listApiTokens(owner, ORG_A, ALICE)).toSatisfy((l: any[]) => l.every((t) => t.revokedAt !== null));
    expect(await apiTokenService.authenticateApiToken(live.token)).toBeNull();
  });

  it("write token follows the owner's current role", async () => {
    const w = await apiTokenService.createApiToken(memberActor, input({ scope: "write" }));
    await memberRepo.updateMemberRole(ORG_A, memberId as any, "admin");
    expect(await apiTokenService.authenticateApiToken(w.token)).toEqual({ userId: ALICE, orgId: ORG_A, role: "admin" });
  });
});
