toolUseResult.originalFile:
import type {
  IsoTimestamp,
  OrgId,
  TenantScoped,
  UserId,
} from "./common";

/**
 * `read` tokens act as a `viewer` whatever the owner's role; `write` tokens act
 * as the owner's current role in the organization.
 */
export type ApiTokenScope = "read" | "write";

/**
 * A personal API token as the rest of the app sees it. The secret and its hash
 * never appear on this type — the plaintext is returned once, by
 * `createApiToken`, and only the hash is stored.
 */
export interface ApiToken extends TenantScoped {
  readonly id: string;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  /** First 12 characters of the secret, kept so users can recognise a token. */
  readonly prefix: string;
  readonly expiresAt: IsoTimestamp;
  readonly lastUsedAt: IsoTimestamp | null;
  readonly revokedAt: IsoTimestamp | null;
  readonly createdAt: IsoTimestamp;
}
